<script>
/* ============================================================
   Coin renderer — pure 2D canvas, procedural, deterministic.
   Simulates a 3D spinning+flipping metallic coin with:
   - vertical axis rotation (yaw) and horizontal flip (pitch)
   - reeded edge visible when the coin turns
   - metallic radial shading + a raking specular highlight
   - two distinct faces (emblem vs denomination)
   ============================================================ */

const PALETTES = {
  hero:   {base:'#d8a93a', hi:'#fff2c4', lo:'#7a5a12', rim:'#4a3608', edge:'#b8922e', ink:'#4a3608'},
  bronze: {base:'#b87333', hi:'#ffd9a8', lo:'#5e3413', rim:'#3a1f0a', edge:'#8a5322', ink:'#3a1f0a'},
  silver: {base:'#c9ccd4', hi:'#ffffff', lo:'#6f7480', rim:'#3d4048', edge:'#a3a7b0', ink:'#3d4048'},
  gold:   {base:'#e8b437', hi:'#fff6cf', lo:'#8a6410', rim:'#4d3706', edge:'#c69a24', ink:'#4d3706'},
  black:  {base:'#26262e', hi:'#8f93ff', lo:'#0a0a0e', rim:'#050507', edge:'#3a3a48', ink:'#a9adff'}
};

function mix(a,b,t){
  const pa=hex(a),pb=hex(b);
  return `rgb(${Math.round(pa[0]+(pb[0]-pa[0])*t)},${Math.round(pa[1]+(pb[1]-pa[1])*t)},${Math.round(pa[2]+(pb[2]-pa[2])*t)})`;
}
function hex(c){
  if(c[0]==='#'){c=c.slice(1);return [parseInt(c.slice(0,2),16),parseInt(c.slice(2,4),16),parseInt(c.slice(4,6),16)];}
  const m=c.match(/\d+/g);return [+m[0],+m[1],+m[2]];
}

/* Draw a coin at a given loop time t into ctx sized WxH.
   pal: palette. faceKind: 'hero' controls text style choices via labels obj. */
function drawCoin(ctx, W, H, t, pal, labels){
  ctx.clearRect(0,0,W,H);
  const cx=W/2, cy=H/2;
  const R = Math.min(W,H)*0.40;    // coin radius (leaves margin so it never touches edges)
  const thick = R*0.12;            // physical half-thickness projected

  // --- rotation angles ---
  // yaw: full vertical-axis spin; pitch: flip about horizontal axis (slower, so both faces appear)
  const yaw   = t * Math.PI * 2.0;             // 0..2pi
  const pitch = t * Math.PI * 2.0 * 0.5 + 0.35; // half rate -> flips over the loop

  // The visible face is determined by combined orientation.
  // Coin normal z-component after yaw*pitch: cos(yaw)*cos(pitch)
  const nz = Math.cos(yaw)*Math.cos(pitch);
  const faceFront = nz >= 0;

  // foreshorten: width shrinks with yaw, height shrinks with pitch
  const sx = Math.abs(Math.cos(yaw));   // horizontal squash
  const sy = Math.abs(Math.cos(pitch)); // vertical squash
  // effective ellipse radii of the face
  const rx = Math.max(R*sx, 0.6);
  const ry = Math.max(R*sy, 0.6);

  // How "edge-on" the coin is (0 = flat facing us, 1 = edge on)
  const edgeOn = 1 - Math.min(sx,sy); // rough measure

  // ---- draw the reeded EDGE band (the side of the coin) ----
  // Visible thickness on screen depends on how much the coin is turned.
  // When turned about yaw, edge shows on left/right; about pitch, top/bottom.
  drawEdge(ctx,cx,cy,R,thick,yaw,pitch,pal);

  // ---- draw the FACE as an ellipse with metallic shading ----
  ctx.save();
  ctx.translate(cx,cy);

  // face ellipse path
  function faceEllipse(scale){
    ctx.beginPath();
    ctx.ellipse(0,0,rx*scale,ry*scale,0,0,Math.PI*2);
  }

  // rim ring
  faceEllipse(1);
  ctx.fillStyle = pal.rim;
  ctx.fill();

  // main metallic body: radial gradient offset by light direction to fake specular rake
  // Light direction rotates opposite to yaw so highlight rakes across as coin turns.
  const lightAng = -yaw*0.8 + 0.4;
  const lx = Math.cos(lightAng), ly = Math.sin(lightAng)*0.5;
  faceEllipse(0.94);
  const g = ctx.createRadialGradient(
      lx*rx*0.5, ly*ry*0.5, Math.min(rx,ry)*0.05,
      0,0, Math.max(rx,ry));
  g.addColorStop(0, pal.hi);
  g.addColorStop(0.35, pal.base);
  g.addColorStop(0.8, mix(pal.base,pal.lo,0.6));
  g.addColorStop(1, pal.lo);
  ctx.fillStyle=g;
  ctx.fill();

  // brushed metal micro-shading rings
  ctx.save();
  faceEllipse(0.94); ctx.clip();
  for(let i=0;i<6;i++){
    const rr = (i+1)/6;
    faceEllipse(0.94*rr);
    ctx.strokeStyle = i%2? 'rgba(255,255,255,0.05)':'rgba(0,0,0,0.06)';
    ctx.lineWidth=2;
    ctx.stroke();
  }
  ctx.restore();

  // inner recessed field
  faceEllipse(0.78);
  ctx.strokeStyle = 'rgba(0,0,0,0.35)';
  ctx.lineWidth = Math.max(2, R*0.02);
  ctx.stroke();

  // ---- emblem / denomination (skip if too edge-on to see) ----
  const faceVisible = Math.min(sx,sy) > 0.20;
  if(faceVisible){
    ctx.save();
    // squash the emblem drawing to match face foreshortening
    ctx.scale(rx/R, ry/R);
    const alpha = Math.min(1,(Math.min(sx,sy)-0.15)/0.35);
    ctx.globalAlpha = alpha;
    if(faceFront){
      drawEmblem(ctx,R,pal,lightAng,labels);
    }else{
      drawBack(ctx,R,pal,lightAng,labels);
    }
    ctx.restore();
  }

  // ---- traveling specular highlight sweep across whole face ----
  faceEllipse(0.94);
  ctx.save();
  ctx.clip();
  const sweepX = Math.cos(lightAng)*rx*1.2;
  const sweepY = Math.sin(lightAng)*ry*1.2;
  const sg = ctx.createLinearGradient(-sweepX,-sweepY,sweepX,sweepY);
  sg.addColorStop(0,'rgba(255,255,255,0)');
  sg.addColorStop(0.46,'rgba(255,255,255,0)');
  sg.addColorStop(0.5, pal===PALETTES.black?'rgba(150,155,255,0.55)':'rgba(255,255,255,0.55)');
  sg.addColorStop(0.54,'rgba(255,255,255,0)');
  sg.addColorStop(1,'rgba(255,255,255,0)');
  ctx.fillStyle=sg;
  faceEllipse(0.94); ctx.fill();
  ctx.restore();

  // outer rim highlight
  faceEllipse(0.97);
  ctx.strokeStyle='rgba(255,255,255,0.18)';
  ctx.lineWidth=Math.max(1,R*0.012);
  ctx.stroke();

  ctx.restore();
}

/* Reeded edge: draw the thickness band behind the face.
   We render ridges around the visible perimeter offset. */
function drawEdge(ctx,cx,cy,R,thick,yaw,pitch,pal){
  // Direction the coin thickness is offset on screen.
  // When yaw != 0 the edge shows to one side; when pitch != 0 shows top/bottom.
  const ox = Math.sin(yaw)*thick*Math.cos(pitch);
  const oy = Math.sin(pitch)*thick;
  const sx = Math.abs(Math.cos(yaw));
  const sy = Math.abs(Math.cos(pitch));
  const rx = Math.max(R*sx,0.6), ry=Math.max(R*sy,0.6);

  // Only draw edge band if there is meaningful offset (coin turned)
  const off = Math.hypot(ox,oy);
  if(off < 1) return;

  ctx.save();
  // Build band by drawing displaced ellipse then reeding lines.
  ctx.translate(cx,cy);

  // Base edge shape: two ellipses offset, fill between via polygon strips.
  const N=64;
  ctx.beginPath();
  for(let i=0;i<=N;i++){
    const a=i/N*Math.PI*2;
    const x=Math.cos(a)*rx, y=Math.sin(a)*ry;
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  }
  for(let i=N;i>=0;i--){
    const a=i/N*Math.PI*2;
    const x=Math.cos(a)*rx+ox, y=Math.sin(a)*ry+oy;
    ctx.lineTo(x,y);
  }
  ctx.closePath();
  const eg=ctx.createLinearGradient(-rx,0,rx,0);
  eg.addColorStop(0,pal.rim);
  eg.addColorStop(0.5,pal.edge);
  eg.addColorStop(1,pal.rim);
  ctx.fillStyle=eg;
  ctx.fill();

  // reeding ridges: short lines connecting the two rims
  ctx.strokeStyle='rgba(0,0,0,0.35)';
  ctx.lineWidth=1.2;
  for(let i=0;i<N;i++){
    const a=i/N*Math.PI*2;
    const x=Math.cos(a)*rx, y=Math.sin(a)*ry;
    // only ridges on the outward-facing part of band
    const dot = (x*ox + y*oy);
    if(dot>0){
      ctx.beginPath();
      ctx.moveTo(x,y);
      ctx.lineTo(x+ox,y+oy);
      const shade = (i%2)? 'rgba(255,255,255,0.22)':'rgba(0,0,0,0.30)';
      ctx.strokeStyle=shade;
      ctx.stroke();
    }
  }
  ctx.restore();
}

/* FRONT face: embossed star/mint emblem in raised relief */
function drawEmblem(ctx,R,pal,lightAng,labels){
  ctx.save();
  const emb=(dx,dy,drawFn)=>{
    // shadow (dark, offset away from light)
    ctx.save();ctx.translate(-Math.cos(lightAng)*R*0.02,-Math.sin(lightAng)*R*0.02);
    ctx.fillStyle='rgba(0,0,0,0.45)';drawFn();ctx.restore();
    // highlight (toward light)
    ctx.save();ctx.translate(Math.cos(lightAng)*R*0.015,Math.sin(lightAng)*R*0.015);
    ctx.fillStyle=mix(pal.hi,pal.base,0.2);drawFn();ctx.restore();
    // body
    ctx.save();ctx.fillStyle=mix(pal.base,pal.hi,0.35);drawFn();ctx.restore();
  };

  // central star
  const points=8, ro=R*0.34, ri=R*0.15;
  const star=()=>{
    ctx.beginPath();
    for(let i=0;i<points*2;i++){
      const a=i/(points*2)*Math.PI*2 - Math.PI/2;
      const rr=i%2?ri:ro;
      const x=Math.cos(a)*rr,y=Math.sin(a)*rr;
      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    }
    ctx.closePath();ctx.fill();
  };
  emb(0,0,star);

  // center medallion "W"
  ctx.fillStyle=pal.ink;
  ctx.beginPath();ctx.arc(0,0,R*0.13,0,Math.PI*2);ctx.fill();
  ctx.fillStyle=mix(pal.hi,pal.base,0.3);
  ctx.font=`900 ${R*0.20}px 'Segoe UI',sans-serif`;
  ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('W',0,R*0.01);

  // circular text ring
  drawArcText(ctx, labels.top||'WASTEDTOKEN MINT', R*0.58, -Math.PI/2, pal.ink, R*0.075, true);
  drawArcText(ctx, labels.bottomFront||'★ CERTIFIED ★', R*0.58, Math.PI/2, pal.ink, R*0.07, false);

  ctx.restore();
}

/* BACK face: denomination token count */
function drawBack(ctx,R,pal,lightAng,labels){
  ctx.save();
  // laurel-ish dashed ring
  ctx.strokeStyle=mix(pal.base,pal.lo,0.4);
  ctx.lineWidth=R*0.02;
  ctx.beginPath();ctx.arc(0,0,R*0.55,0,Math.PI*2);ctx.stroke();

  // big token number
  const emb=(txt,size,y)=>{
    ctx.font=`900 ${size}px 'Segoe UI',sans-serif`;
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillText(txt,-R*0.012,y-R*0.012);
    ctx.fillStyle=mix(pal.hi,pal.base,0.25);ctx.fillText(txt,R*0.008,y+R*0.008);
    ctx.fillStyle=mix(pal.base,pal.hi,0.4);ctx.fillText(txt,0,y);
  };
  emb(labels.value||'10,000', R*0.30, -R*0.05);
  emb('TOKENS', R*0.14, R*0.22);

  drawArcText(ctx, labels.top||'WASTEDTOKEN MINT', R*0.70, -Math.PI/2, pal.ink, R*0.075, true);
  drawArcText(ctx, labels.bottomBack||'PHYSICAL CHALLENGE COIN', R*0.70, Math.PI/2, pal.ink, R*0.055, false);
  ctx.restore();
}

function drawArcText(ctx,text,radius,centerAngle,color,size,topArc){
  ctx.save();
  ctx.fillStyle=color;
  ctx.font=`800 ${size}px 'Segoe UI',sans-serif`;
  ctx.textAlign='center';ctx.textBaseline='middle';
  const chars=text.split('');
  const step=(size*0.9)/radius;
  const total=(chars.length-1)*step;
  chars.forEach((ch,i)=>{
    let a;
    if(topArc){ a = centerAngle - total/2 + i*step; }
    else { a = centerAngle + total/2 - i*step; }
    ctx.save();
    ctx.rotate(a+Math.PI/2);
    ctx.translate(0,-radius* (topArc?1:1));
    if(!topArc)ctx.rotate(Math.PI);
    ctx.fillText(ch,0,0);
    ctx.restore();
  });
  ctx.restore();
}

